struct HilbertMo {    struct Query { int l, r, idx; long long ord; };    vector<Query> queries;    static long long hilbert(int x, int y, int n) {        long long d = 0;        for (int s = n >> 1; s; s >>= 1) {            int rx = (x & s) > 0, ry = (y & s) > 0;            d += (long long)s * s * ((3 * rx) ^ ry);            if (!ry) {                if (rx) { x = s - 1 - x; y = s - 1 - y; }                swap(x, y);            }        }        return d;    }    HilbertMo(int n, vector<pair<int,int>>& qs) {        int hn = 1;        while (hn < n) hn <<= 1;        for (int i = 0; i < (int)qs.size(); i++)            queries.push_back({qs[i].first, qs[i].second, i,                               hilbert(qs[i].first, qs[i].second, hn)});        sort(queries.begin(), queries.end(),             [](const Query& a, const Query& b) {            return a.ord < b.ord;        });    }    template<typename Add, typename Rem, typename Ans>    void run(Add add, Rem rem, Ans ans) {        int L = 0, R = -1;        for (auto& [l, r, idx, ord] : queries) {            while (R < r) add(++R);            while (L > l) add(--L);            while (R > r) rem(R--);            while (L < l) rem(L++);            ans(idx);        }    }};